    ]
  },
  {
    "alert_id": "EX3_003",
    "title": "TDF renal monitoring overdue by >6 months",
    "message": "Guidelines require serum creatinine and eGFR monitoring for patients on TDF-containing regimens. The patient's last creatinine was 196 days ago (2025-08-12) and no renal function test has been ordered today. TDF is associated with chronic kidney disease, acute kidney injury, and Fanconi syndrome. While the previous creatinine of 72 umol/L was normal, the >6-month gap without monitoring is a guideline deviation, especially in a patient with new-onset metabolic abnormalities and obesity.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Order serum creatinine and eGFR today to fulfil TDF monitoring requirements. Continue routine renal monitoring per guideline schedule.",
